from __future__ import annotations


_ALIGNMENTS = ("left", "right", "center")


def _cell_text(value) -> str:
    """Return a value as table cell text, escaping pipes."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    """Pad cell text to *width* according to *align*."""
    padding = width - len(text)
    if align == "right":
        return " " * padding + text
    if align == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, align: str | None) -> str:
    """Build one delimiter cell of *width* dashes."""
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _alignments(align: list[str | None] | None, columns: int) -> list[str | None]:
    """Validate and normalize the per-column alignment list."""
    if align is None:
        return [None] * columns

    try:
        given = list(align)
    except TypeError:
        raise ValueError("align must contain one entry per column") from None

    if len(given) != columns:
        raise ValueError("align must contain one entry per column")

    for value in given:
        if value is not None and value not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {value!r}")
    return given


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)
    alignments = _alignments(align, columns)

    header_cells = [_cell_text(value) for value in header]
    row_cells: list[list[str]] = []
    for row in rows:
        cells = [_cell_text(value) for value in row]
        if len(cells) > columns:
            raise ValueError("row has more cells than the header")
        cells.extend([""] * (columns - len(cells)))
        row_cells.append(cells)

    widths: list[int] = []
    for column in range(columns):
        width = len(header_cells[column])
        for cells in row_cells:
            width = max(width, len(cells[column]))
        widths.append(max(width, 3))

    def render(cells: list[str]) -> str:
        padded = (
            _pad(cell, width, alignment)
            for cell, width, alignment in zip(cells, widths, alignments)
        )
        return "| " + " | ".join(padded) + " |"

    lines = [render(header_cells)]

    delimiter = " | ".join(
        _delimiter_cell(width, alignment)
        for width, alignment in zip(widths, alignments)
    )
    lines.append("| " + delimiter + " |")

    lines.extend(render(cells) for cells in row_cells)
    return "\n".join(lines)


def _split_cells(line: str) -> list[str]:
    """Split one table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]

    cells: list[str] = []
    current: list[str] = []
    index = 0
    while index < len(line):
        char = line[index]
        if char == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            current.append("\\|")
            index += 2
        elif char == "|":
            cells.append("".join(current).strip().replace("\\|", "|"))
            current = []
            index += 1
        else:
            current.append(char)
            index += 1

    cells.append("".join(current).strip().replace("\\|", "|"))
    return cells


def _delimiter_alignment(cell: str) -> str | None:
    """Validate one delimiter cell and return its alignment."""
    left = cell.startswith(":")
    right = cell.endswith(":")
    body = cell[1 if left else 0 : -1 if right else None]
    if not body or any(char != "-" for char in body):
        raise ValueError(f"invalid delimiter cell: {cell!r}")

    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("text does not contain a table")

    header = _split_cells(lines[0])
    delimiter = _split_cells(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments = [_delimiter_alignment(cell) for cell in delimiter]

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _split_cells(line)
        if len(cells) != len(header):
            raise ValueError("row has a different number of cells than the header")
        rows.append(cells)

    return header, rows, alignments
